import base64
import os
import logging

logger = logging.getLogger(__name__)

QR_PNG_B64 = ""

def get_merchant_qr_path() -> str:
    """Ensures the Google Pay Merchant QR PNG exists on disk and returns its path."""
    qr_path = os.path.join(os.path.dirname(__file__), "gpay_merchant_qr.png")
    if not os.path.exists(qr_path) or os.path.getsize(qr_path) == 0:
        try:
            with open(qr_path, "wb") as f:
                f.write(base64.b64decode(QR_PNG_B64.strip()))
            logger.info(f"Generated merchant QR image at {qr_path}")
        except Exception as e:
            logger.error(f"Failed to generate merchant QR from base64: {e}")
            return ""
    return qr_path
